// === Tab: mySketch ===
let mainradius = 300;
let Yangle = 0;
let speed = 0.01;
let offset = 10;
let ring = 2.75;
let noiseScale = 0.05; // 噪音的缩放比例
let noiseStrength = 0; // 噪音强度

function setup() {
  createCanvas(500, 500, WEBGL);
  frameRate(40);
}

function draw() {
  if (keyPressed) {
    if (key == CODED) {
      if (keyCode == UP) {
        ring += 1;
      }
      if (keyCode == DOWN) {
        if (ring > 1) {
          ring -= 1;
        }
      }
    }
  }

  background(0);
  translate(width / 2, height / 2);
  rotateY(Yangle);
  rotateX(-90);
  rotateZ(-10);

  for (y = -mainradius / 2; y < mainradius / 2; y += round(ring)) {
    //strokeWeight(ring * sin(y + offset));
		strokeWeight(2);
    let t = 0;
    while (t < TWO_PI) {
      let radius = sqrt(pow((mainradius - 40) / 2, 2) - pow(y, 2));
      let x = radius * cos(t);
      let z = radius * sin(t);

      // 计算噪音值
      let noiseValue = noise(x * noiseScale, y * noiseScale, z * noiseScale + offset);

      // 只将噪音效果应用到 x 和 z 坐标
      x += noiseValue * noiseStrength * noise(x);
      z += noiseValue * noiseStrength;

      // 获取点在屏幕上的位置
      let screenXPos = screenX(x, y, z);
      let screenYPos = screenY(x, y, z);

      // 计算点到屏幕中心的距离
      let distToCenter = dist(screenXPos, screenYPos, width / 2, height / 2);

      // 根据距离计算透明度，距离越远透明度越低
      let alpha = map(distToCenter, 0, radius * 1.2, 0, 100);

      // 设置颜色和透明度
      stroke(255, alpha);
      point(x, y, z);
      t += 0.1;
    }
  }

  Yangle += speed;
  offset += 0.1; // 继续增加 offset 以产生流动效果
}

